"use client";
import {
  createNexusClient,
  type EthereumProvider,
  type NexusClient,
  type NexusNetwork,
} from "@avail-project/nexus-core";
import { getCoinbaseRates } from "@avail-project/nexus-core/utils";
import {
  type ChainBalance,
  convertTokenReadableAmountToBigInt,
  type GetRouteSupportedChains,
  type LegacyAllowanceHookData,
  type LegacyIntentHookData,
  normalizeIntentBalances,
  normalizeSupportedChains,
  type OnAllowanceHookData,
  type OnIntentHookData,
  type OnSwapIntentHookData,
  populateChainsWithTokens,
  resolveTokenContractAddress,
  type SupportedChainsAndTokensResult,
  type TokenBalance,
} from "./better-intent-compat";

export type UserAsset = TokenBalance & {
  breakdown: (ChainBalance & {
    balance: string;
    balanceInFiat: number;
    chain: ChainBalance["chain"];
    contractAddress: string;
    decimals: number;
    symbol: string;
  })[];
  balanceInFiat?: number;
};

type SupportedChainsResult = SupportedChainsAndTokensResult;

type BalanceFetchTiming = {
  runId: number;
  source: string;
  startTimeMs: number;
  walletAddress: string | null;
};

import {
  createContext,
  type RefObject,
  useCallback,
  useContext,
  useEffect,
  useMemo,
  useRef,
  useState,
} from "react";
import { useAccountEffect } from "wagmi";
import {
  isSwapSupportedBySdkChainList,
  type SdkChainListWithSwapSupport,
} from "../common/utils/constant";
import {
  buildUsdPeggedSymbolSet,
  DEFAULT_USD_PEGGED_TOKEN_SYMBOLS,
  fetchCoinbaseUsdRate,
  fetchCoinGeckoUsdRate,
  getCoinbaseSymbolCandidates,
  normalizeTokenSymbol,
  resolveBaseSymbol,
  toFinitePositiveNumber,
  TOKEN_PRICE_PEGS,
  TokenPricingError,
  USD_PEGGED_FALLBACK_RATE,
} from "../common/utils/token-pricing";

interface NexusContextType {
  allowance: RefObject<OnAllowanceHookData | null>;
  attachEventHooks: () => void;
  bridgableBalance: UserAsset[] | null;
  bridgableBalanceLoading: boolean;
  deinitializeNexus: () => Promise<void>;
  exchangeRate: Record<string, number> | null;
  fetchBridgableBalance: () => Promise<void>;
  fetchSwapBalance: () => Promise<UserAsset[] | null>;
  getFiatValue: (amount: number, token: string) => number;
  getRouteSupportedChains?: GetRouteSupportedChains;
  handleInit: (
    provider: EthereumProvider,
    accountAddress?: string,
  ) => Promise<void>;
  initializeNexus: (
    provider: EthereumProvider,
    accountAddress?: string,
  ) => Promise<void>;
  intent: RefObject<OnIntentHookData | null>;
  loading: boolean;
  network?: NexusNetwork;
  nexusSDK: NexusClient | null;
  resolveTokenUsdRate: (tokenSymbol: string) => Promise<number | null>;
  setAllowance: (data: OnAllowanceHookData | null) => void;
  setIntent: (data: OnIntentHookData | null) => void;
  supportedChainsAndTokens: SupportedChainsAndTokensResult | null;
  swapBalance: UserAsset[] | null;
  swapBalanceLoading: boolean;
  swapIntent: RefObject<OnSwapIntentHookData | null>;
  swapSupportedChainsAndTokens: SupportedChainsResult | null;
}

export const NexusContext = createContext<NexusContextType | undefined>(
  undefined,
);

type NexusProviderProps = {
  children: React.ReactNode;
  config?: {
    network?: NexusNetwork;
    debug?: boolean;
    mode?: "deposit" | "swap" | "send";
  };
};

const defaultConfig: Required<NexusProviderProps["config"]> = {
  network: "canary",
  debug: true,
  mode: "swap",
};

type SourceBalance = ChainBalance & {
  balanceInFiat?: number | string;
  value?: number | string;
};

type TokenBalanceWithSources = Omit<TokenBalance, "chainBalances"> & {
  balanceInFiat?: number | string;
  breakdown?: SourceBalance[];
  chainBalances?: SourceBalance[];
  value?: number | string;
};

const sumSourceBalances = (sources: SourceBalance[]) =>
  sources.reduce((sum, source) => {
    const balance = Number.parseFloat(String(source.balance ?? "0"));
    return Number.isFinite(balance) && balance > 0 ? sum + balance : sum;
  }, 0);

const getSourceBalanceChainId = (source: SourceBalance) =>
  source.chain?.id ?? (source as SourceBalance & { chainId?: number }).chainId;

const normalizeAccountAddress = (address?: string | null) => {
  const normalized = address?.trim().toLowerCase();
  return normalized || null;
};

const filterUnsupportedSwapSources = (
  assets: TokenBalance[] | null,
  swapSupportedChains?: SdkChainListWithSwapSupport,
): TokenBalance[] | null => {
  if (!assets) {
    return null;
  }

  return assets.flatMap((asset) => {
    const assetWithSources = asset as TokenBalanceWithSources;
    const sourceBalances =
      assetWithSources.chainBalances ?? assetWithSources.breakdown ?? [];
    const filteredSources = sourceBalances.filter((source) =>
      isSwapSupportedBySdkChainList(
        getSourceBalanceChainId(source),
        swapSupportedChains,
      ),
    );

    if (filteredSources.length === 0) {
      return [];
    }

    return [
      {
        ...asset,
        balance: String(sumSourceBalances(filteredSources)),
        balanceInFiat: undefined,
        breakdown: filteredSources,
        chainBalances: filteredSources,
        value: "0",
      } as TokenBalance,
    ];
  });
};

const attachSdkCompat = (
  client: NexusClient,
  chainsRef: { current: SupportedChainsAndTokensResult | null }
) => {
  const c = client as any;
  if (!c.convertTokenReadableAmountToBigInt) {
    c.convertTokenReadableAmountToBigInt = (
      amount: string,
      tokenSymbol: string,
      chainId: number
    ) => {
      return convertTokenReadableAmountToBigInt(
        amount,
        tokenSymbol,
        chainId,
        chainsRef.current
      );
    };
  }
  if (!c.bridge) {
    c.bridge = async (params: any, options?: any) => {
      const toTokenAddress = resolveTokenContractAddress(
        params.toChainId,
        params.toTokenSymbol,
        chainsRef.current
      );
      return client.swapWithExactOut(
        {
          toAmountRaw: params.toAmountRaw,
          toChainId: params.toChainId,
          toTokenAddress,
          sources: params.sources?.map((s: any) =>
            typeof s === "number" ? { chainId: s } : s
          ),
        },
        options
      );
    };
  }
  if (!c.bridgeAndTransfer) {
    c.bridgeAndTransfer = async (params: any, options?: any) => {
      const toTokenAddress = resolveTokenContractAddress(
        params.toChainId,
        params.toTokenSymbol,
        chainsRef.current
      );
      const res = await client.swapWithExactOut(
        {
          toAmountRaw: params.toAmountRaw,
          toChainId: params.toChainId,
          toTokenAddress,
          sources: params.sources?.map((s: any) =>
            typeof s === "number" ? { chainId: s } : s
          ),
        },
        options
      );
      return {
        ...res,
        bridgeSkipped: false,
        bridgeResult: res,
        execute: {
          txExplorerUrl: res.intentExplorerUrl,
        },
      };
    };
  }
  if (!c.bridgeAndExecute) {
    c.bridgeAndExecute = async (params: any, options?: any) => {
      const toTokenAddress = resolveTokenContractAddress(
        params.toChainId,
        params.toTokenSymbol,
        chainsRef.current
      );
      return client.swapAndExecute(
        {
          toChainId: params.toChainId,
          toTokenAddress,
          toAmountRaw: params.toAmountRaw,
          sources: params.sources?.map((s: any) =>
            typeof s === "number" ? { chainId: s } : s
          ),
          execute: params.execute,
        },
        options
      );
    };
  }
  if (!c.getBalancesForBridge) {
    c.getBalancesForBridge = async () => {
      return client.getBalances();
    };
  }
};

const NexusProvider = ({
  children,
  config = defaultConfig,
}: NexusProviderProps) => {
  const stableConfig = useMemo(
    () => ({ ...defaultConfig, ...config }),
    [config],
  );

  console.log("NEXUS PROVIDER CONFIG", stableConfig, defaultConfig, config);

  const sdkRef = useRef<NexusClient | null>(null);
  const [sdk, setSdk] = useState<NexusClient | null>(null);
  const [nexusSDK, setNexusSDK] = useState<NexusClient | null>(null);
  const [loading, setLoading] = useState<boolean>(false);
  const supportedChainsAndTokens =
    useRef<SupportedChainsAndTokensResult | null>(null);
  const swapSupportedChainsAndTokens = useRef<SupportedChainsResult | null>(
    null,
  );
  const [supportedChainsAndTokensState, setSupportedChainsAndTokensState] =
    useState<SupportedChainsAndTokensResult | null>(null);
  const [
    swapSupportedChainsAndTokensState,
    setSwapSupportedChainsAndTokensState,
  ] = useState<SupportedChainsResult | null>(null);
  const [bridgableBalance, setBridgableBalance] = useState<UserAsset[] | null>(
    null,
  );
  const [bridgableBalanceLoading, setBridgableBalanceLoading] =
    useState(false);
  const [swapBalance, setSwapBalance] = useState<UserAsset[] | null>(null);
  const [swapBalanceLoading, setSwapBalanceLoading] = useState(false);
  const swapBalanceRef = useRef<UserAsset[] | null>(null);
  const [exchangeRateState, setExchangeRateState] = useState<Record<
    string,
    number
  > | null>(null);
  const exchangeRate = useRef<Record<string, number> | null>(null);
  const coinbaseUsdRateCache = useRef<Record<string, number>>({});
  const coinbaseUsdRateRequests = useRef<
    Record<string, Promise<number | null>>
  >({});
  const initRequest = useRef<Promise<void> | null>(null);
  const initializedAccountAddress = useRef<string | null>(null);
  const bridgableBalanceRequest = useRef<Promise<UserAsset[] | null> | null>(
    null,
  );
  const swapBalanceRequest = useRef<Promise<UserAsset[] | null> | null>(null);
  const lastSwapBalanceFetchAt = useRef(0);
  const balanceFetchRunId = useRef(0);
  const latestBalanceFetchRunId = useRef(0);
  const usdPeggedSymbols = useRef<Set<string>>(
    new Set(DEFAULT_USD_PEGGED_TOKEN_SYMBOLS),
  );

  const intent = useRef<OnIntentHookData | null>(null);
  const allowance = useRef<OnAllowanceHookData | null>(null);
  const swapIntent = useRef<OnSwapIntentHookData | null>(null);
  const initializedRef = useRef(false);

  const startBalanceFetchTiming = useCallback((source: string) => {
    const runId = balanceFetchRunId.current + 1;
    balanceFetchRunId.current = runId;
    latestBalanceFetchRunId.current = runId;
    const walletAddress = initializedAccountAddress.current;
    const startTimeMs = Date.now();
    const timing: BalanceFetchTiming = {
      runId,
      source,
      startTimeMs,
      walletAddress,
    };

    console.log("[NexusProvider] balance fetch start", {
      runId,
      walletAddress,
      source,
      dateNow: startTimeMs,
      date: new Date(startTimeMs),
    });

    return timing;
  }, []);

  const finishBalanceFetchTiming = useCallback(
    (timing: BalanceFetchTiming, status: "resolved" | "failed" = "resolved") => {
      if (latestBalanceFetchRunId.current !== timing.runId) {
        return;
      }

      const endTimeMs = Date.now();
      const fetchDurationMs = endTimeMs - timing.startTimeMs;

      console.log("[NexusProvider] balance fetch end", {
        runId: timing.runId,
        walletAddress: timing.walletAddress,
        source: timing.source,
        status,
        dateNow: endTimeMs,
        date: new Date(endTimeMs),
      });
      console.log("[NexusProvider] balance fetch total", {
        runId: timing.runId,
        walletAddress: timing.walletAddress,
        source: timing.source,
        status,
        totalTimeSeconds: fetchDurationMs / 1000,
        elapsedMs: fetchDurationMs,
        dateNow: endTimeMs,
      });
    },
    [],
  );

  useEffect(() => {
    let cancelled = false;
    console.log("NEXUS CONFIG", stableConfig);
    const nextSdk = createNexusClient({
      clientId: "nexus-elements",
      network: stableConfig.network,
      debug: stableConfig.debug,
    });
    attachSdkCompat(nextSdk, supportedChainsAndTokens);

    void nextSdk
      .initialize()
      .then(() => {
        if (cancelled) {
          return;
        }
        if (initializedRef.current) {
          nextSdk.destroy();
          return;
        }
        sdkRef.current = nextSdk;
        setSdk(nextSdk);
        console.log("SupportedChains", nextSdk.getSupportedChains());
      })
      .catch((err) => {
        console.error(
          "Failed to initialize default read-only Nexus client:",
          err,
        );
      });

    return () => {
      cancelled = true;
      nextSdk.destroy();
      if (sdkRef.current === nextSdk) {
        sdkRef.current = null;
      }
      setSdk(null);
      setNexusSDK(null);
    };
  }, [stableConfig]);

  const cacheUsdRate = useCallback((tokenSymbol: string, usdRate: number) => {
    const normalized = normalizeTokenSymbol(tokenSymbol);
    const rate = toFinitePositiveNumber(usdRate);
    if (!(normalized && rate)) {
      return;
    }

    coinbaseUsdRateCache.current[normalized] = rate;
    const currentRates = exchangeRate.current ?? {};
    if (currentRates[normalized] === rate) {
      return;
    }

    const nextRates = {
      ...currentRates,
      [normalized]: rate,
    };
    exchangeRate.current = nextRates;
    setExchangeRateState(nextRates);
  }, []);

  const getUsdRateFromLocalSources = useCallback((tokenSymbol: string) => {
    const normalizedSymbol = normalizeTokenSymbol(tokenSymbol);
    if (!normalizedSymbol) {
      return 0;
    }

    const _debug = normalizedSymbol === "WCBTC" || normalizedSymbol === "CBTC";
    if (_debug) {
      console.debug(`[PRICING DEBUG] resolving "${normalizedSymbol}"`, {
        candidates: getCoinbaseSymbolCandidates(normalizedSymbol),
        exchangeRateKeys: Object.keys(exchangeRate.current ?? {}),
        hasBTC: exchangeRate.current?.["BTC"],
        pegBase: resolveBaseSymbol(normalizedSymbol),
      });
    }

    // 1. Direct SDK / cache lookup for the original symbol candidates
    for (const candidate of getCoinbaseSymbolCandidates(normalizedSymbol)) {
      const sdkRate = toFinitePositiveNumber(exchangeRate.current?.[candidate]);
      if (sdkRate) {
        return sdkRate;
      }

      const cachedRate = toFinitePositiveNumber(
        coinbaseUsdRateCache.current[candidate],
      );
      if (cachedRate) {
        return cachedRate;
      }
    }

    // 2. Explicit pegging fallback (e.g. WCBTC→BTC, WETH→ETH)
    const baseSymbol = resolveBaseSymbol(normalizedSymbol);
    if (baseSymbol) {
      if (usdPeggedSymbols.current.has(baseSymbol) || baseSymbol === "USD") {
        if (_debug)
          console.debug(
            `[PRICING DEBUG] "${normalizedSymbol}" → base "${baseSymbol}" is USD-pegged, returning 1`,
          );
        return USD_PEGGED_FALLBACK_RATE;
      }

      for (const candidate of getCoinbaseSymbolCandidates(baseSymbol)) {
        const sdkRate = toFinitePositiveNumber(
          exchangeRate.current?.[candidate],
        );
        if (sdkRate) {
          if (_debug)
            console.debug(
              `[PRICING DEBUG] "${normalizedSymbol}" → base "${baseSymbol}" → SDK candidate "${candidate}" = ${sdkRate}`,
            );
          return sdkRate;
        }

        const cachedRate = toFinitePositiveNumber(
          coinbaseUsdRateCache.current[candidate],
        );
        if (cachedRate) {
          if (_debug)
            console.debug(
              `[PRICING DEBUG] "${normalizedSymbol}" → base "${baseSymbol}" → cached candidate "${candidate}" = ${cachedRate}`,
            );
          return cachedRate;
        }
      }
      if (_debug)
        console.debug(
          `[PRICING DEBUG] "${normalizedSymbol}" → base "${baseSymbol}" NOT found in any source`,
        );
    }

    // 3. Dynamic USD-pegged set
    if (!baseSymbol && usdPeggedSymbols.current.has(normalizedSymbol)) {
      if (_debug)
        console.debug(
          `[PRICING DEBUG] "${normalizedSymbol}" → in usdPeggedSymbols, returning 1`,
        );
      return USD_PEGGED_FALLBACK_RATE;
    }

    if (_debug)
      console.debug(
        `[PRICING DEBUG] "${normalizedSymbol}" → NO RATE FOUND, returning 0`,
      );
    return 0;
  }, []);

  useEffect(() => {
    if (!sdk) {
      return;
    }

    let cancelled = false;
    let list: SupportedChainsAndTokensResult | null = null;
    let swapList: SupportedChainsAndTokensResult | null = null;
    try {
      list = normalizeSupportedChains(sdk.getSupportedChains());
      swapList = list;
    } catch (e) {
      console.warn(
        "SDK getSupportedChains failed (likely not initialized yet):",
        e,
      );
    }

    supportedChainsAndTokens.current = list;
    swapSupportedChainsAndTokens.current = swapList;
    usdPeggedSymbols.current = buildUsdPeggedSymbolSet(list);
    setSupportedChainsAndTokensState(list);
    setSwapSupportedChainsAndTokensState(swapList);

    sdk
      .getTokens({ limit: 1000 })
      .then((tokenPage) => {
        if (cancelled || !tokenPage?.tokens?.length || !list) {
          return;
        }
        const enriched = populateChainsWithTokens(list, tokenPage.tokens);
        supportedChainsAndTokens.current = enriched;
        swapSupportedChainsAndTokens.current = enriched;
        usdPeggedSymbols.current = buildUsdPeggedSymbolSet(enriched);
        setSupportedChainsAndTokensState(enriched);
        setSwapSupportedChainsAndTokensState(enriched);
      })
      .catch(() => {});

    void getCoinbaseRates()
      .then((rates) => {
        if (cancelled) {
          return;
        }
        const usdPerUnit: Record<string, number> = {};

        for (const [symbol, value] of Object.entries(rates)) {
          const unitsPerUsd = Number.parseFloat(String(value));
          if (Number.isFinite(unitsPerUsd) && unitsPerUsd > 0) {
            usdPerUnit[normalizeTokenSymbol(symbol)] = 1 / unitsPerUsd;
          }
        }
        exchangeRate.current = usdPerUnit;
        setExchangeRateState(usdPerUnit);
      })
      .catch((error) => {
        if (!cancelled) {
          console.warn("Unable to preload Nexus rates", error);
        }
      });

    return () => {
      cancelled = true;
    };
  }, [sdk, stableConfig.network]);

  const normalizeUserAssetFiatValues = useCallback(
    (assets: TokenBalance[] | null): UserAsset[] | null => {
      if (!assets) {
        return null;
      }

      return assets.map((asset) => {
        const assetWithSources = asset as TokenBalanceWithSources;
        let computedAssetUsd = 0;
        const sourceBalances =
          assetWithSources.chainBalances ?? assetWithSources.breakdown ?? [];

        const breakdown = sourceBalances.map((entry) => {
          const balance = Number.parseFloat(String(entry.balance ?? "0"));
          const safeBalance =
            Number.isFinite(balance) && balance > 0 ? balance : 0;
          const entrySymbol = normalizeTokenSymbol(
            entry.symbol ?? asset.symbol,
          );
          const existingUsd = Number.parseFloat(
            String(entry.value ?? entry.balanceInFiat ?? "0"),
          );
          const safeExistingUsd =
            Number.isFinite(existingUsd) && existingUsd >= 0 ? existingUsd : 0;

          const hasPeg = Boolean(resolveBaseSymbol(entrySymbol));

          let normalizedUsd = safeExistingUsd;
          if (safeBalance > 0 && normalizedUsd <= 0) {
            const rate = getUsdRateFromLocalSources(
              entry.symbol ?? asset.symbol,
            );
            if (rate > 0) {
              normalizedUsd = safeBalance * rate;
            }
          }

          computedAssetUsd += normalizedUsd;
          return {
            ...entry,
            balanceInFiat: normalizedUsd,
          };
        });

        const assetBalance = Number.parseFloat(String(asset.balance ?? "0"));
        const safeAssetBalance =
          Number.isFinite(assetBalance) && assetBalance > 0 ? assetBalance : 0;
        const rawAssetUsd = Number.parseFloat(
          String(
            assetWithSources.value ?? assetWithSources.balanceInFiat ?? "0",
          ),
        );
        const safeAssetUsd =
          Number.isFinite(rawAssetUsd) && rawAssetUsd >= 0 ? rawAssetUsd : 0;
        const assetHasPeg = Boolean(
          resolveBaseSymbol(normalizeTokenSymbol(asset.symbol)),
        );

        let normalizedAssetUsd = safeAssetUsd;
        if (normalizedAssetUsd <= 0 || assetHasPeg) {
          if (computedAssetUsd > 0) {
            normalizedAssetUsd = computedAssetUsd;
          } else if (safeAssetBalance > 0) {
            const rate = getUsdRateFromLocalSources(asset.symbol);
            if (rate > 0) {
              normalizedAssetUsd = safeAssetBalance * rate;
            }
          }
        }

        return {
          ...asset,
          balanceInFiat: normalizedAssetUsd,
          breakdown,
        } as UserAsset;
      });
    },
    [getUsdRateFromLocalSources],
  );

  const resolveTokenUsdRate = useCallback(
    async (tokenSymbol: string) => {
      const normalizedSymbol = normalizeTokenSymbol(tokenSymbol);
      if (!normalizedSymbol) {
        return null;
      }

      const sdkRate = toFinitePositiveNumber(
        exchangeRate.current?.[normalizedSymbol],
      );
      if (sdkRate) {
        return sdkRate;
      }

      const cachedRate = toFinitePositiveNumber(
        coinbaseUsdRateCache.current[normalizedSymbol],
      );
      if (cachedRate) {
        return cachedRate;
      }

      const inFlightRequest = coinbaseUsdRateRequests.current[normalizedSymbol];
      if (inFlightRequest) {
        return inFlightRequest;
      }

      const requestPromise = (async (): Promise<number | null> => {
        // 1. Check SDK / cache candidates for the original symbol
        for (const candidate of getCoinbaseSymbolCandidates(normalizedSymbol)) {
          const sdkCandidateRate = toFinitePositiveNumber(
            exchangeRate.current?.[candidate],
          );
          if (sdkCandidateRate) {
            cacheUsdRate(normalizedSymbol, sdkCandidateRate);
            return sdkCandidateRate;
          }

          const cachedCandidateRate = toFinitePositiveNumber(
            coinbaseUsdRateCache.current[candidate],
          );
          if (cachedCandidateRate) {
            cacheUsdRate(normalizedSymbol, cachedCandidateRate);
            return cachedCandidateRate;
          }
        }

        // 2. Try Coinbase API for the original symbol
        const coinbaseRate = await fetchCoinbaseUsdRate(normalizedSymbol);
        if (coinbaseRate) {
          cacheUsdRate(normalizedSymbol, coinbaseRate);
          return coinbaseRate;
        }

        const coinGeckoRate = await fetchCoinGeckoUsdRate(normalizedSymbol);
        if (coinGeckoRate) {
          cacheUsdRate(normalizedSymbol, coinGeckoRate);
          return coinGeckoRate;
        }

        if (usdPeggedSymbols.current.has(normalizedSymbol)) {
          cacheUsdRate(normalizedSymbol, USD_PEGGED_FALLBACK_RATE);
          return USD_PEGGED_FALLBACK_RATE;
        }

        // 5. All paths exhausted — throw a pricing error
        throw new TokenPricingError(normalizedSymbol);
      })();

      coinbaseUsdRateRequests.current[normalizedSymbol] = requestPromise;
      try {
        return await requestPromise;
      } finally {
        delete coinbaseUsdRateRequests.current[normalizedSymbol];
      }
    },
    [cacheUsdRate],
  );

  const setIntent = useCallback((data: OnIntentHookData | null) => {
    intent.current = data;
  }, []);

  const setAllowance = useCallback((data: OnAllowanceHookData | null) => {
    allowance.current = data;
  }, []);

  const setupNexus = useCallback(async () => {
    const activeSdk = sdkRef.current;
    if (!activeSdk) {
      return;
    }
    const activeAccountAddress = initializedAccountAddress.current;
    const isCurrentSdkRun = () =>
      sdkRef.current === activeSdk &&
      initializedAccountAddress.current === activeAccountAddress;
    const list = normalizeSupportedChains(activeSdk.getSupportedChains());
    supportedChainsAndTokens.current = list ?? null;
    setSupportedChainsAndTokensState(list ?? null);
    usdPeggedSymbols.current = buildUsdPeggedSymbolSet(list ?? null);
    const swapList = list;
    swapSupportedChainsAndTokens.current = swapList ?? null;
    setSwapSupportedChainsAndTokensState(swapList ?? null);
    setBridgableBalanceLoading(true);
    setSwapBalanceLoading(true);
    const balanceTiming = startBalanceFetchTiming("setup");
    let balanceTimingStatus: "resolved" | "failed" = "resolved";
    try {
      const [tokensResult, swapBalanceResult, rates] =
        await Promise.allSettled([
          activeSdk.getTokens({ limit: 1000 }).catch(() => null),
          activeSdk.getBalancesForSwap(),
          getCoinbaseRates(),
        ]);

      let currentList = list;
      if (
        tokensResult?.status === "fulfilled" &&
        tokensResult.value?.tokens &&
        currentList
      ) {
        currentList = populateChainsWithTokens(
          currentList,
          tokensResult.value.tokens
        );
        supportedChainsAndTokens.current = currentList;
        swapSupportedChainsAndTokens.current = currentList;
        usdPeggedSymbols.current = buildUsdPeggedSymbolSet(currentList);
        setSupportedChainsAndTokensState(currentList);
        setSwapSupportedChainsAndTokensState(currentList);
      }

      if (rates?.status === "fulfilled") {
        const usdPerUnit: Record<string, number> = {};

        for (const [symbol, value] of Object.entries(rates.value)) {
          const normalized = normalizeTokenSymbol(symbol);
          if (TOKEN_PRICE_PEGS[normalized]) continue;

          const unitsPerUsd = Number.parseFloat(String(value));
          if (Number.isFinite(unitsPerUsd) && unitsPerUsd > 0) {
            usdPerUnit[normalized] = 1 / unitsPerUsd;
          }
        }
        exchangeRate.current = usdPerUnit;
        setExchangeRateState(usdPerUnit);
      }

      if (!isCurrentSdkRun()) {
        return;
      }

      if (swapBalanceResult.status === "fulfilled") {
        const rawSwapBalance = normalizeIntentBalances(
          swapBalanceResult.value,
          currentList ?? list ?? []
        );
        const filteredSwapBalance = filterUnsupportedSwapSources(
          rawSwapBalance,
          currentList ?? swapList
        );
        const normalizedSwapBalance =
          normalizeUserAssetFiatValues(filteredSwapBalance);
        console.log(
          "[NexusProvider] getBalancesForSwap:init raw",
          swapBalanceResult.value,
        );
        setSwapBalance(normalizedSwapBalance);
        setBridgableBalance(normalizedSwapBalance);
      }
    } catch (error) {
      balanceTimingStatus = "failed";
      throw error;
    } finally {
      finishBalanceFetchTiming(balanceTiming, balanceTimingStatus);
      if (isCurrentSdkRun()) {
        setBridgableBalanceLoading(false);
        setSwapBalanceLoading(false);
      }
    }
  }, [
    finishBalanceFetchTiming,
    normalizeUserAssetFiatValues,
    startBalanceFetchTiming,
  ]);

  const initializeNexus = useCallback(
    async (provider: EthereumProvider, accountAddress?: string) => {
      setLoading(true);
      try {
        console.log("INITIALIZE NEXUS CONFIG", stableConfig);
        const previousSdk = sdkRef.current;
        const shouldDestroyPreviousSdk = Boolean(previousSdk);
        const nextSdk = createNexusClient({
          clientId: "nexus-elements",
          network: stableConfig.network,
          debug: stableConfig.debug,
        });
        attachSdkCompat(nextSdk, supportedChainsAndTokens);

        await nextSdk.initialize();
        await nextSdk.setEVMProvider(provider);

        if (
          shouldDestroyPreviousSdk &&
          previousSdk &&
          previousSdk !== nextSdk
        ) {
          previousSdk.destroy();
        }

        sdkRef.current = nextSdk;
        setSdk(nextSdk);
        initializedRef.current = true;
        initializedAccountAddress.current =
          normalizeAccountAddress(accountAddress);
        setNexusSDK(nextSdk);
      } catch (error) {
        console.error("Error initializing Nexus:", error);
        throw error;
      } finally {
        setLoading(false);
      }
    },
    [stableConfig],
  );

  const deinitializeNexus = useCallback(() => {
    try {
      const activeSdk = nexusSDK ?? sdkRef.current;
      if (!activeSdk) {
        return Promise.resolve();
      }
      activeSdk.destroy();
      if (sdkRef.current === activeSdk) {
        sdkRef.current = null;
      }
      initializedRef.current = false;
      initializedAccountAddress.current = null;
      setSdk(null);
      setNexusSDK(null);
      setBridgableBalance(null);
      swapBalanceRef.current = null;
      setSwapBalance(null);
      intent.current = null;
      swapIntent.current = null;
      allowance.current = null;
      const invalidatedRunId = balanceFetchRunId.current + 1;
      balanceFetchRunId.current = invalidatedRunId;
      latestBalanceFetchRunId.current = invalidatedRunId;
      setLoading(false);
      setBridgableBalanceLoading(false);
      setSwapBalanceLoading(false);
    } catch (error) {
      console.error("Error deinitializing Nexus:", error);
    }
    return Promise.resolve();
  }, [nexusSDK]);

  const attachEventHooks = useCallback(() => {
    // Dummy signature for backward compatibility, hooks are now per-call
  }, []);

  const handleInit = useCallback(
    async (provider: EthereumProvider, accountAddress?: string) => {
      const nextAccountAddress = normalizeAccountAddress(accountAddress);
      const currentAccountAddress = initializedAccountAddress.current;
      const isAccountChange =
        Boolean(currentAccountAddress && nextAccountAddress) &&
        currentAccountAddress !== nextAccountAddress;

      if (
        initializedRef.current &&
        (!nextAccountAddress || currentAccountAddress === nextAccountAddress)
      ) {
        return;
      }

      if (loading && initRequest.current) {
        await initRequest.current;
        if (
          initializedRef.current &&
          (!nextAccountAddress ||
            initializedAccountAddress.current === nextAccountAddress)
        ) {
          return;
        }
      }

      if (!provider || typeof provider.request !== "function") {
        throw new Error("Invalid EIP-1193 provider");
      }

      const nextInitRequest = (async () => {
        if (initializedRef.current) {
          if (isAccountChange) {
            console.log("[NexusProvider] wallet address changed; reinitializing Nexus", {
              previousWalletAddress: currentAccountAddress,
              nextWalletAddress: nextAccountAddress,
              dateNow: Date.now(),
              date: new Date(),
            });
          }
          await deinitializeNexus();
        }
        await initializeNexus(provider, nextAccountAddress ?? undefined);
        await setupNexus();
        attachEventHooks();
      })();

      initRequest.current = nextInitRequest;
      try {
        await nextInitRequest;
      } catch (error) {
        console.error("Error during Nexus setup flow:", error);
        throw error;
      } finally {
        if (initRequest.current === nextInitRequest) {
          initRequest.current = null;
        }
      }
    },
    [
      loading,
      initializeNexus,
      deinitializeNexus,
      setupNexus,
      attachEventHooks,
    ],
  );

  const fetchBridgableBalance = useCallback(async () => {
    let request = bridgableBalanceRequest.current;
    let balanceTiming: BalanceFetchTiming | null = null;
    let balanceTimingStatus: "resolved" | "failed" = "resolved";
    try {
      const activeSdk = sdkRef.current;
      if (!activeSdk) {
        return;
      }
      const activeAccountAddress = initializedAccountAddress.current;
      balanceTiming = startBalanceFetchTiming("bridge-refresh");
      setBridgableBalanceLoading(true);
      const updatedBalance = await activeSdk.getBalancesForSwap();
      if (
        sdkRef.current !== activeSdk ||
        initializedAccountAddress.current !== activeAccountAddress
      ) {
        return;
      }
      const rawBalance = normalizeIntentBalances(
        updatedBalance,
        supportedChainsAndTokens.current ?? []
      );
      setBridgableBalance(normalizeUserAssetFiatValues(rawBalance));
    } catch (error) {
      balanceTimingStatus = "failed";
      console.error("Error fetching bridgable balance:", error);
    } finally {
      if (balanceTiming) {
        finishBalanceFetchTiming(balanceTiming, balanceTimingStatus);
      }
      setBridgableBalanceLoading(false);
      if (request && bridgableBalanceRequest.current === request) {
        bridgableBalanceRequest.current = null;
      }
    }
  }, [
    finishBalanceFetchTiming,
    normalizeUserAssetFiatValues,
    startBalanceFetchTiming,
  ]);

  const fetchSwapBalance = useCallback(async () => {
    const activeSdk = sdkRef.current;
    if (!activeSdk) {
      return null;
    }
    const activeAccountAddress = initializedAccountAddress.current;
    const balanceTiming = startBalanceFetchTiming("swap-refresh");
    let balanceTimingStatus: "resolved" | "failed" = "resolved";
    try {
      setSwapBalanceLoading(true);
      const updatedBalance = await activeSdk.getBalancesForSwap();
      if (
        sdkRef.current !== activeSdk ||
        initializedAccountAddress.current !== activeAccountAddress
      ) {
        return null;
      }
      const rawSwapBalance = normalizeIntentBalances(
        updatedBalance,
        swapSupportedChainsAndTokens.current ?? []
      );
      const filteredSwapBalance = filterUnsupportedSwapSources(
        rawSwapBalance,
        swapSupportedChainsAndTokens.current,
      );
      const normalizedSwapBalance =
        normalizeUserAssetFiatValues(filteredSwapBalance);
      console.log(
        "[NexusProvider] getBalancesForSwap:refresh raw",
        updatedBalance,
      );
      setSwapBalance(normalizedSwapBalance);
      setBridgableBalance(normalizedSwapBalance);
      return normalizedSwapBalance;
    } catch (error) {
      balanceTimingStatus = "failed";
      console.error("Error fetching swap balance:", error);
      return null;
    } finally {
      finishBalanceFetchTiming(balanceTiming, balanceTimingStatus);
      if (
        sdkRef.current === activeSdk &&
        initializedAccountAddress.current === activeAccountAddress
      ) {
        setSwapBalanceLoading(false);
      }
    }
  }, [
    finishBalanceFetchTiming,
    normalizeUserAssetFiatValues,
    startBalanceFetchTiming,
  ]);

  const getRouteSupportedChains = useCallback<GetRouteSupportedChains>(
    async (constraints) => {
      const activeSdk = sdkRef.current;
      if (!activeSdk) {
        throw new Error("Nexus SDK is not initialized");
      }
      return normalizeSupportedChains(
        await activeSdk.getSupportedChainsForRoute(constraints)
      );
    },
    []
  );

  const getFiatValue = useCallback(
    (amount: number, token: string) => {
      const rate = getUsdRateFromLocalSources(token);
      const normalized = normalizeTokenSymbol(token);
      if (normalized === "WCBTC" || normalized === "CBTC") {
        console.debug(
          `[PRICING] getFiatValue("${token}") → rate=${rate}, amount=${amount}, result=${rate * amount}`,
        );
      }
      return rate * amount;
    },
    [getUsdRateFromLocalSources],
  );

  // Backfill USD values once rates arrive so downstream selectors/max logic
  // do not treat supported assets as $0 simply due to timing.
  useEffect(() => {
    if (!exchangeRateState) {
      return;
    }
    setSwapBalance((prev) => normalizeUserAssetFiatValues(prev));
    setBridgableBalance((prev) => normalizeUserAssetFiatValues(prev));
  }, [exchangeRateState, normalizeUserAssetFiatValues]);

  useAccountEffect({
    onDisconnect() {
      deinitializeNexus();
    },
  });

  const value = useMemo(
    () => ({
      nexusSDK,
      initializeNexus,
      deinitializeNexus,
      attachEventHooks,
      intent,
      allowance,
      handleInit,
      supportedChainsAndTokens: supportedChainsAndTokensState,
      swapSupportedChainsAndTokens: swapSupportedChainsAndTokensState,
      bridgableBalance,
      bridgableBalanceLoading,
      swapBalance,
      swapBalanceLoading,
      network: config?.network,
      loading,
      fetchBridgableBalance,
      fetchSwapBalance,
      setAllowance,
      setIntent,
      swapIntent,
      exchangeRate: exchangeRateState,
      getFiatValue,
      getRouteSupportedChains,
      resolveTokenUsdRate,
    }),
    [
      nexusSDK,
      initializeNexus,
      deinitializeNexus,
      attachEventHooks,
      handleInit,
      bridgableBalance,
      bridgableBalanceLoading,
      swapBalance,
      swapBalanceLoading,
      config?.network,
      loading,
      fetchBridgableBalance,
      fetchSwapBalance,
      setAllowance,
      setIntent,
      exchangeRateState,
      getFiatValue,
      getRouteSupportedChains,
      resolveTokenUsdRate,
      supportedChainsAndTokensState,
      swapSupportedChainsAndTokensState,
    ],
  );
  return (
    <NexusContext.Provider value={value}>{children}</NexusContext.Provider>
  );
};

export function useNexus() {
  const context = useContext(NexusContext);
  if (!context) {
    throw new Error("useNexus must be used within a NexusProvider");
  }
  return context;
}

export default NexusProvider;

// biome-ignore-all lint/suspicious/useNumberToFixedDigitsArgument: Decimal.toFixed() preserves every fractional digit; a digits argument would round balances.

import Decimal from "decimal.js";
import type { ChainBalance, TokenBalance } from "./better-intent-compat";

const BalanceDecimal = Decimal.clone({ precision: 80 });

interface BalanceFields {
  /** Spendable amount. UI token options retain this compatibility field. */
  balance?: string;
  balanceInFiat?: number | string;
  totalBalance?: string;
  totalBalanceInFiat?: number | string;
  usableBalance?: string;
}

export interface TokenOptionBalances {
  /** Always sourced from usableBalance; used for inputs, percentages and quotes. */
  balance: string;
  balanceInFiat: string;
  totalBalance: string;
  totalBalanceInFiat: string;
}

type NormalizedChainBalance = ChainBalance & {
  balanceInFiat: number;
  totalBalanceInFiat: number;
  usableBalance?: string;
  totalBalance?: string;
};

export type NormalizedUserAsset = TokenBalance & {
  balanceInFiat: number;
  totalBalanceInFiat: number;
  breakdown: NormalizedChainBalance[];
  chainBalances: NormalizedChainBalance[];
};

const nonNegative = (value: string | number | undefined) => {
  try {
    const parsed = new BalanceDecimal(value ?? 0);
    return parsed.isFinite() && parsed.gte(0) ? parsed : new BalanceDecimal(0);
  } catch {
    return new BalanceDecimal(0);
  }
};

export const getUsableBalance = (balance?: BalanceFields): string =>
  balance?.usableBalance ?? balance?.balance ?? "0";

export const getTotalBalance = (balance?: BalanceFields): string =>
  balance?.totalBalance ?? balance?.balance ?? "0";

export const getTotalBalanceInFiat = (
  balance?: BalanceFields
): number | string =>
  balance?.totalBalanceInFiat ?? balance?.balanceInFiat ?? 0;

export function toTokenOptionBalances(
  balance: BalanceFields
): TokenOptionBalances {
  return {
    balance: getUsableBalance(balance),
    balanceInFiat: `$${nonNegative(balance.balanceInFiat).toFixed()}`,
    totalBalance: getTotalBalance(balance),
    totalBalanceInFiat: `$${nonNegative(getTotalBalanceInFiat(balance)).toFixed(2)}`,
  };
}

const FORMATTED_AMOUNT = /^[+-]?(?:\d+\.?\d*|\.\d+)(?:e[+-]?\d+)?/i;
const parseFormatted = (value: string | number | undefined) =>
  nonNegative(
    typeof value === "string"
      ? value.replace(/[$,\s]/g, "").match(FORMATTED_AMOUNT)?.[0]
      : value
  );

export function sumTokenOptionBalances(
  balances: BalanceFields[]
): TokenOptionBalances {
  let usable = new BalanceDecimal(0);
  let total = new BalanceDecimal(0);
  let usableUsd = new BalanceDecimal(0);
  let totalUsd = new BalanceDecimal(0);
  for (const balance of balances) {
    usable = usable.plus(parseFormatted(getUsableBalance(balance)));
    total = total.plus(parseFormatted(getTotalBalance(balance)));
    usableUsd = usableUsd.plus(parseFormatted(balance.balanceInFiat));
    totalUsd = totalUsd.plus(parseFormatted(getTotalBalanceInFiat(balance)));
  }
  return toTokenOptionBalances({
    usableBalance: usable.toFixed(),
    totalBalance: total.toFixed(),
    balanceInFiat: usableUsd.toFixed(),
    totalBalanceInFiat: totalUsd.toFixed(),
  });
}

export function isAmountAboveUsableBalance(
  balance: BalanceFields,
  amount: string,
  mode: "token" | "usd" = "token"
): boolean {
  const available =
    mode === "usd" ? balance.balanceInFiat : getUsableBalance(balance);
  return parseFormatted(amount).gt(parseFormatted(available));
}

/** SDK value is the USD value of usableBalance, including for native assets. */
export function normalizeUserAssets(
  assets: TokenBalance[] | null,
  getUsdRate: (symbol: string) => number = () => 0,
  includeSource?: (source: ChainBalance) => boolean
): NormalizedUserAsset[] | null {
  if (!assets) {
    return null;
  }
  return assets.flatMap((asset) => {
    const legacyAsset = asset as TokenBalance & { breakdown?: ChainBalance[] };
    const sources = asset.chainBalances ?? legacyAsset.breakdown ?? [];
    const included = includeSource ? sources.filter(includeSource) : sources;
    if (includeSource && included.length === 0) {
      return [];
    }

    const breakdown = included.map((source): NormalizedChainBalance => {
      const total = nonNegative(getTotalBalance(source));
      const usable = BalanceDecimal.min(
        nonNegative(getUsableBalance(source)),
        total
      );
      const value = nonNegative(source.value);
      const rate =
        usable.gt(0) && value.gt(0)
          ? value.div(usable)
          : nonNegative(getUsdRate(source.symbol ?? asset.symbol));
      const usableUsd = usable.mul(rate);
      return {
        ...source,
        balance: usable.toFixed(),
        usableBalance: usable.toFixed(),
        totalBalance: total.toFixed(),
        value: usableUsd.toFixed(),
        balanceInFiat: usableUsd.toNumber(),
        totalBalanceInFiat: total.mul(rate).toNumber(),
      };
    });

    const sums = sumTokenOptionBalances(breakdown);
    return [
      {
        ...asset,
        balance: sums.balance,
        usableBalance: sums.balance,
        totalBalance: sums.totalBalance,
        value: parseFormatted(sums.balanceInFiat).toFixed(),
        balanceInFiat: parseFormatted(sums.balanceInFiat).toNumber(),
        totalBalanceInFiat: parseFormatted(sums.totalBalanceInFiat).toNumber(),
        breakdown,
        chainBalances: breakdown,
      },
    ];
  });
}

